#!/usr/bin/env bash
# Qwen3-32B TP=4 + LoRA smoke test
#
# Adds --enable_lora=true + --lora_modules to the base-only tp4 script.
# Uses the dummy adapter generated by make_qwen3_32b_dummy_adapter.py
# (r=8, alpha=16, std=1e-4, B initialised to 0 to match PEFT convention).
set -e

source /usr/local/Ascend/ascend-toolkit/set_env.sh
source /usr/local/Ascend/nnal/atb/set_env.sh

MODEL_PATH=/export/home/models/Qwen3-32B
ADAPTER_PATH=/export/home/caihao.40/lora_adapters/DeepNews-LoRA-Qwen3-32B
XLLM_BIN=/export/home/caihao.40/xllm_multilora/build/lib.linux-aarch64-cpython-311/xllm/xllm
LOG_DIR=/export/home/caihao.40/log_multilora/qwen3_32b_tp4_lora
mkdir -p "$LOG_DIR"

NNODES=4
TP_SIZE=4
START_DEVICE=0
START_PORT=18100
MASTER_ADDR=127.0.0.1:19100
HCCL_IF_BASE_PORT=44500

export LD_LIBRARY_PATH=/export/home/caihao.40/xllm_multilora/third_party/xllm_ops/build:${LD_LIBRARY_PATH:-}
unset http_proxy https_proxy HTTP_PROXY HTTPS_PROXY 2>/dev/null || true

# Kill any stale ranks
for i in 0 1 2 3; do
  port=$((START_PORT + i))
  pkill -9 -f "port $port" 2>/dev/null || true
done
sleep 2

for i in 0 1 2 3; do
  port=$((START_PORT + i))
  device=$((START_DEVICE + i))
  log_file="${LOG_DIR}/rank${i}.log"

  echo "[INFO] rank $i: port=$port device=npu:$device log=$log_file"

  setsid env \
    LD_LIBRARY_PATH="${LD_LIBRARY_PATH}" \
    HCCL_IF_BASE_PORT="${HCCL_IF_BASE_PORT}" \
    "${XLLM_BIN}" \
      --model "${MODEL_PATH}" \
      --host 127.0.0.1 \
      --port "${port}" \
      --devices "npu:${device}" \
      --master_node_addr "${MASTER_ADDR}" \
      --nnodes ${NNODES} \
      --node_rank ${i} \
      --tp_size ${TP_SIZE} \
      --max_memory_utilization 0.86 \
      --max_tokens_per_batch 10240 \
      --max_seqs_per_batch 256 \
      --block_size 128 \
      --communication_backend hccl \
      --enable_prefix_cache=false \
      --enable_chunked_prefill=false \
      --enable_schedule_overlap=true \
      --enable_lora=true \
      --lora_modules="news=${ADAPTER_PATH}" \
      --max_loras=16 \
      --max_lora_rank=64 \
      --npu_kernel_backend=TORCH \
      > "$log_file" 2>&1 < /dev/null &
done

echo "[OK] launched 4 ranks with LoRA; entry port 18100"
